import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { format } from "prettier";
import {
  radiusPrimitives,
  radiusPresets,
  borderWidths,
  borderStyles,
  borderRoles,
  focusRing,
  shadowLayers,
  shadowValue,
} from "../packages/tokens/src/surfaces.ts";
import {
  componentRadii,
  componentShadows,
  componentBorderWidths,
} from "../packages/react/src/tokens/component-surfaces.ts";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const header =
  "/* Generated by scripts/generate-surfaces.mjs. Do not edit. */\n";
const declarations = (entries) =>
  entries.map(([key, value]) => `--dixy-${key}: ${value};`).join("\n");
const radiusRoles = (preset) =>
  Object.entries(radiusPresets[preset]).map(([role, token]) => [
    `radius-${role}`,
    `var(--dixy-radius-${token})`,
  ]);
const radiusCss = `${header}@layer dixy.tokens {
  :root { ${declarations(Object.entries(radiusPrimitives).map(([id, px]) => [`radius-${id}`, id === "full" ? `${px}px` : px === 0 ? "0" : `${px / 16}rem`]))} }
  :root { ${declarations(radiusRoles("md"))} }
  ${Object.keys(radiusPresets)
    .map(
      (preset) =>
        `[data-radius="${preset}"] { ${declarations(radiusRoles(preset))} }`,
    )
    .join("\n")}
  :root, .dixy-theme, [data-radius] { --dixy-radius: var(--dixy-radius-control); }
}\n`;

const borderCss = `${header}@layer dixy.tokens {
  :root {
    ${declarations(Object.entries(borderWidths).map(([id, px]) => [`border-width-${id}`, `${px}px`]))}
    ${declarations(Object.entries(borderStyles).map(([name, value]) => [`border-style-${name}`, value]))}
    --dixy-stroke-width: var(--dixy-border-width-1);
    --dixy-focus-ring-width: var(--dixy-border-width-${focusRing.width});
    --dixy-focus-ring-offset: ${focusRing.offset}px;
  }
  :root, .dixy-theme, [data-appearance], [data-accent], [data-neutral] {
    ${declarations(Object.entries(borderRoles).map(([name, value]) => [`border-${name}`, `${value.width === "1" ? "var(--dixy-stroke-width)" : `var(--dixy-border-width-${value.width})`} var(--dixy-border-style-${value.style}) var(--dixy-color-${value.color.replaceAll(".", "-")})`]))}
  }
}\n`;
const shadowDeclarations = (appearance) =>
  Object.keys(shadowLayers).map((role) => [
    `shadow-${role}`,
    shadowValue(role, appearance),
  ]);
const shadowCss = `${header}@layer dixy.tokens {
  :root { ${declarations(shadowDeclarations("light"))} }
  ${["light", "dark"].map((appearance) => `[data-appearance="${appearance}"] { ${declarations(shadowDeclarations(appearance))} }`).join("\n")}
  :root, .dixy-theme, [data-appearance] { --dixy-shadow: var(--dixy-shadow-overlay); }
  @media (forced-colors: active) {
    :root, [data-appearance] { ${declarations(Object.keys(shadowLayers).map((role) => [`shadow-${role}`, "none"]))} }
  }
}\n`;
// Bind aliases locally so nested appearance/radius scopes resolve in their own context.
const components = `${header}@layer dixy.tokens {
  :root, .dixy-theme, [data-radius] {
    ${declarations(Object.entries(componentRadii).map(([component, role]) => [`${component}-radius`, role === "control" ? "var(--dixy-radius)" : `var(--dixy-radius-${role})`]))}
  }
  :root, .dixy-theme, [data-appearance] {
    ${declarations(Object.entries(componentShadows).map(([component, role]) => [`${component}-shadow`, component === "dialog" ? "var(--dixy-shadow)" : `var(--dixy-shadow-${role})`]))}
  }
  :root, .dixy-theme {
    ${declarations(Object.entries(componentBorderWidths).map(([component, width]) => [`${component}-border-width`, `var(--dixy-stroke-width, var(--dixy-border-width-${width}))`]))}
  }
}\n`;
const outputs = {
  "packages/tokens/src/radius.css": radiusCss,
  "packages/tokens/src/border.css": borderCss,
  "packages/tokens/src/shadow.css": shadowCss,
  "packages/react/src/tokens/component-surfaces.css": components,
};
if (process.argv.includes("--dist")) {
  for (const name of ["radius", "border", "shadow"])
    outputs[`packages/tokens/dist/${name}.css`] =
      outputs[`packages/tokens/src/${name}.css`];
}
for (const [file, raw] of Object.entries(outputs)) {
  const content = await format(raw, { parser: "css" });
  const target = path.join(root, file);
  const current = fs.existsSync(target) ? fs.readFileSync(target, "utf8") : "";
  if (process.argv.includes("--check")) {
    if (content !== current)
      throw new Error(`${file} is stale. Run pnpm tokens:generate.`);
  } else if (content !== current) {
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, content);
  }
}
console.log(
  process.argv.includes("--check")
    ? "Surface tokens match their canonical contracts."
    : "Radius, border, shadow and component aliases generated.",
);
